static int p2d89_emit_bars_basic(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 h[]={-16384,-3072,16384,-3072,16384,3072,-16384,3072};static const p2d89_q14 v[]={-3072,-16384,3072,-16384,3072,16384,-3072,16384};static const p2d89_q14 sl[]={-12288,16384,-6144,16384,12288,-16384,6144,-16384};if(id==P2D89_SHAPE_VERTICAL_BAR){if(!p2d89_i_move(p,0,-14336))return 0;return p2d89_i_line(p,0,14336);}if(id==P2D89_SHAPE_BAR_HORIZONTAL)return p2d89_i_poly(h,4U,1,p);if(id==P2D89_SHAPE_BAR_VERTICAL)return p2d89_i_poly(v,4U,1,p);if(id==P2D89_SHAPE_BAR_SLANTED_FWD)return p2d89_i_poly(sl,4U,1,p);if(id==P2D89_SHAPE_BAR_SLANTED_BACK)return p2d89_i_rot_poly(sl,4U,32768U,1,p);if(id==P2D89_SHAPE_BAR_ROUNDED_HORIZONTAL)return p2d89_i_rounded_rect(16384,4096,4096,p);if(id==P2D89_SHAPE_BAR_ROUNDED_VERTICAL){static const p2d89_q14 tmp[]={-4096,-16384,4096,-16384,4096,16384,-4096,16384};return p2d89_i_poly(tmp,4U,1,p);}return 0;}
const P2D89_Submodule p2d89_submodule_bars_basic = { { P2D89_MODULE_BARS, "bars", "basic", (unsigned int)(sizeof(shapes)/sizeof(shapes[0])) }, shapes, p2d89_emit_bars_basic };
